argv:
$ErrorActionPreference='Stop';$OutputEncoding=[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new();
$p='E:\WebAIBridge';
$o=[ordered]@{path=$p;exists=(Test-Path "$p\.git")};
if($o.exists){
 $o.branch=(git -C $p branch --show-current);
 $o.head=(git -C $p rev-parse HEAD);
 $o.remote=(git -C $p remote get-url origin);
 $o.status=@(git -C $p status --porcelain);
 $o.serverSha=(Get-FileHash "$p\app\server.js" -Algorithm SHA256).Hash.ToLowerInvariant();
}
$o|ConvertTo-Json -Depth 5 -Compress
